// remove is called when a component is unmounted.
export function unsubscribe(name: string, uniqueid: string) {
    const key = name
    const found = namesMap.get(name)
    if (found !== undefined) {
        console.log('pubsub unsubscribe', name, uniqueid)
        found.map.delete(uniqueid)
        if (found.map.size === 0) {
            namesMap.delete(key)
        }
    }
}
